"""Generate ONE copyable Kaggle training script from the tested source modules."""

import ast
from pathlib import Path

from build_onset_kaggle import build as build_preparation


HEADER = '''"""Standalone experimental onset training: paste/run this WHOLE script on Kaggle.

Use the existing trainer notebook with GuitarSet attached and GPU enabled.
No previous manifest, preparation output, repo files or authentication change
is needed. This run audits the attached mono mix/mic, regenerates the tuned
synthetic data, extracts causal short spectra ONCE, then trains a CONTROL and
a RISE model with identical initial shared weights and ordinary batches. Both
use ordinary BCE. RISE adds a zero-initialized projection of positive per-bin
amplitude change against the previous four frames, computed inside ONNX.
Raw features and targets stay unchanged. No paired loss or extra negative weight.
RISE needs 34 past feature frames instead of 30; neither model waits for future
frames. Preparation is deterministic and runs again; it does not require an old
cache. Old attached training output is not overwritten.
Torch/numpy/soundfile must be available; missing onnx/onnxruntime are installed
automatically on Kaggle. Outputs go to a new /kaggle/working/onset-prepared-*.

Share the top-level training_summary.json (its path is printed at the end).
It includes both arms and their full fixed validation threshold curves.
Preserve the WHOLE output directory with Save Version; it includes ONNX models,
checkpoints, contracts, features and probabilities for any later comparison.
On failure, the entry point writes training_failure.json and exits normally to
leave a readable notebook output. Always check ok=true in training_summary.json;
a completed notebook process does not mean training succeeded. Hosting retention
is not guaranteed; keep a copy of the output when it is available.
The ONNX is EXPERIMENTAL with a different input contract. Do not replace the
app's chord/pitch model with it. This run does not measure app credits or the
existing head. An ok result means a complete experiment, not a better model.

Default: 12 epochs PER ARM, 16 blocks/batch, train players00-03, validation04, test05;
both solo and comp, 60/12/12 synthetic groups. Constants TRAIN_EPOCHS and
TRAIN_BATCH_SIZE below may be edited before pasting. CLI also has --epochs,
--batch-size, --input-dir, --output-root and --device.

Generated by dist/build_train_onset_kaggle.py. Edit the source modules then
regenerate; no embedded exec or project imports are used in this file.
"""
'''


def node_text(source, node):
    start = min([node.lineno] + [d.lineno for d in getattr(node, "decorator_list", [])]) - 1
    return "\n".join(source.splitlines()[start:node.end_lineno])


def build(directory):
    chunks = [HEADER]
    preparation = build_preparation(directory)
    for node in ast.parse(preparation).body:
        if isinstance(node, (ast.If, ast.Expr)) or isinstance(node, ast.FunctionDef) and node.name == "main":
            continue
        chunks.append(node_text(preparation, node))
    scorer = (directory / "onset_events.py").read_text()
    for node in ast.parse(scorer).body:
        if isinstance(node, (ast.Import, ast.ImportFrom)) or (
            isinstance(node, (ast.FunctionDef, ast.ClassDef)) and
            node.name in ("Event", "match_events", "percentile", "latch_events")
        ):
            chunks.append(node_text(scorer, node))
    trainer = (directory / "train_short_onset.py").read_text()
    for module in ("onset_ringing.py", "onset_pairs.py", "onset_rise.py"):
        source = (directory / module).read_text()
        for node in ast.parse(source).body:
            if not isinstance(node, ast.Expr):
                chunks.append(node_text(source, node))
    for node in ast.parse(trainer).body:
        if isinstance(node, ast.Expr):
            continue
        if isinstance(node, ast.ImportFrom) and node.module in ("onset_events", "prepare_onset_kaggle", "onset_ringing", "onset_pairs", "onset_rise"):
            continue
        chunks.append(node_text(trainer, node))
    return "\n\n".join(chunks).rstrip() + "\n"


def build_recovery(directory):
    chunks = ['''"""Paste/run this WHOLE script in the existing Kaggle notebook with GPU.
Recovers a control/rise run stopped at ONNX validation. Auto-searches working
and attached input datasets; set RUN_DIR below if more than one run exists.
Uses saved checkpoints and features. Completed training is NEVER repeated.
Only a rise arm that was never started is trained. Incomplete epochs are an error.
Copies the existing output to a new onset-recovered-* directory so the original
remains intact. Preserve this whole directory via Save Version and share its
main training_summary.json. No original audio/manifest preparation is needed.
Final threshold selection and scores use ONNX Runtime for both arms. Strict
probability tolerance remains; discrete event differences are reported explicitly.
"""''']
    trainer = build(directory)
    for node in ast.parse(trainer).body:
        if not isinstance(node, (ast.Expr, ast.If)):
            chunks.append(node_text(trainer, node))
    recovery = (directory / "resume_onset_training.py").read_text()
    for node in ast.parse(recovery).body:
        if isinstance(node, ast.Expr) or isinstance(node, ast.ImportFrom) and node.module == "train_short_onset":
            continue
        chunks.append(node_text(recovery, node))
    return "\n\n".join(chunks).rstrip() + "\n"


if __name__ == "__main__":
    directory = Path(__file__).resolve().parent
    output = directory / "train_onset_kaggle.py"
    output.write_text(build(directory))
    print(output)
    recovery = directory / "resume_onset_kaggle.py"
    recovery.write_text(build_recovery(directory))
    print(recovery)
